const m=v.pem.match(/-----BEGIN CERTIFICATE-----([A-Za-z0-9+/=\s]+)-----END CERTIFICATE-----/);if(!m)throw Error('Paste a PEM block that starts with -----BEGIN CERTIFICATE-----.');
